describe('Login Form Keyboard Navigation', () => {
  beforeEach(() => {
    cy.visit('/login');
  });

  it('should navigate through login form using keyboard arrows and submit successfully', () => {
    // Focus on email input field
    cy.get('[data-testid="email-input"]').click();
    cy.get('[data-testid="email-input"]').type('user@example.com');

    // Tab to password field
    cy.get('[data-testid="password-input"]').click();
    cy.get('[data-testid="password-input"]').type('password123');

    // Tab to submit button
    cy.get('[data-testid="login-button"]').click();

    // Verify login was successful
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="welcome-message"]').should('be.visible');
    cy.get('[data-testid="welcome-message"]').should('contain', 'Welcome back');
  });

  it('should handle focus and tab order correctly when form is empty', () => {
    // Focus on email input field
    cy.get('[data-testid="email-input"]').click();
    cy.get('[data-testid="email-input"]').type('');

    // Tab to password field
    cy.get('[data-testid="password-input"]').click();
    cy.get('[data-testid="password-input"]').type('');

    // Tab to submit button
    cy.get('[data-testid="login-button"]').click();

    // Verify error message appears
    cy.get('[data-testid="error-message"]').should('be.visible');
    cy.get('[data-testid="error-message"]').should('contain', 'Please fill in both fields');

    // Tab back to email field
    cy.get('[data-testid="password-input"]').click();
    cy.get('[data-testid="password-input"]').type('password');

    // Tab to submit button again
    cy.get('[data-testid="login-button"]').click();

    // Verify login was successful
    cy.url().should('include', '/dashboard');
    cy.get('[data-testid="welcome-message"]').should('be.visible');
  });
});
